/* CMANS Office Hub v5 — project workspace, daily work and reliable print previews */
const logoV5='data:image/png;base64,';
const v5Style=`<style>
#cmansPreview{position:fixed;inset:0;z-index:9999;background:rgba(20,32,52,.72);display:flex;align-items:center;justify-content:center;padding:18px}
#cmansPreview .preview-shell{background:white;width:min(1050px,98vw);height:min(94vh,1100px);border-radius:12px;display:flex;flex-direction:column;overflow:hidden;box-shadow:0 20px 70px #101c35aa}
#cmansPreview .preview-bar{display:flex;gap:9px;align-items:center;justify-content:space-between;background:#eef2f8;padding:12px 17px}
#cmansPreview iframe{border:0;flex:1;width:100%;background:white}
.project-tabs{display:flex;flex-wrap:wrap;gap:8px;margin:14px 0}.project-tabs button{padding:10px 15px;border-radius:8px}
.v5-card{background:white;border:1px solid #dce4ef;border-radius:12px;padding:16px;margin:12px 0}
.v5-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:12px}
.v5-kpi{background:#f5f8fc;border-radius:10px;padding:14px}.v5-kpi small{display:block;color:#64748b}.v5-kpi strong{font-size:23px;color:#20334f}
.v5-file{display:flex;justify-content:space-between;gap:12px;padding:12px;border-bottom:1px solid #e7edf4;align-items:center}
.v5-file small{color:#65758e}.v5-file button{white-space:nowrap}
.v5-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:14px}
.v5-note{color:#66758c;font-size:12px;margin:10px 0}
.v5-compare-legend{display:flex;gap:8px;flex-wrap:wrap;margin:10px 0}.v5-compare-legend span{padding:6px 12px;border-radius:7px;color:white;font-weight:600}
@media(max-width:720px){.v5-file{flex-wrap:wrap}}
</style>`;
document.head.insertAdjacentHTML('beforeend',v5Style);
const v5filesDB=new Map();
let projectTabV5='overview',projectFileCategory='Drawings';
let dailyLogsV5=v4store('dailywork',[]);
let dailyLinesV5=[{project:projectDB[0]?.id||'',task:'',category:'CAD',description:'',hours:2,progress:0,issues:'',next:''}];
let handoverModeV5='letter';
const projectButtonsV5=()=>`<div class="project-tabs">${[['overview','ภาพรวมโครงการ'],['details','ข้อมูลโครงการ / สร้างโครงการ'],['files','เอกสารโครงการ / Revision']].map(([id,title])=>`<button class="${projectTabV5===id?'primary':'secondary'}" onclick="projectTabV5='${id}';render()">${title}</button>`).join('')}</div>`;
const projectSelectorV5=()=>`<label>เลือกโครงการ</label><select onchange="selectedPID=this.value;render()">${projectDB.map(p=>`<option value="${E(p.id)}" ${p.id===selectedPID?'selected':''}>${E(p.name)} · ${E(p.id)}</option>`).join('')}</select>`;
function projectOverviewV5(){let p=projectDB.find(x=>x.id===selectedPID)||projectDB[0];if(!p)return '<p>ยังไม่มีโครงการ</p>';let gap=Number(p.progress)-Number(p.planned);let docs=(fileIndexV5[p.id]||[]);return `<div class="card"><div class="form-head"><h3>Project Overview / ภาพรวมโครงการ</h3>${button('+ สร้างโครงการ','projectTabV5="details";newProject()','primary')}</div>${projectSelectorV5()}<div class="v5-grid" style="margin-top:14px"><div class="v5-kpi"><small>ประเภทโครงการ</small><strong style="font-size:16px">${E(p.type)}</strong></div><div class="v5-kpi"><small>พื้นที่ (ตร.ม.)</small><strong>${Number(p.area||0).toLocaleString('th-TH')}</strong></div><div class="v5-kpi"><small>Budget</small><strong style="font-size:18px">${fmt(p.budget)}</strong></div><div class="v5-kpi"><small>Actual / Planned</small><strong>${p.progress}% / ${p.planned}%</strong></div></div><div class="v5-grid" style="margin-top:14px"><div><b>Client</b><p>${E(p.client||'—')}</p></div><div><b>Location</b><p>${E(p.location||'—')}</p></div><div><b>Timeline</b><p>${E(p.start||'—')} – ${E(p.end||'—')}</p></div><div><b>Schedule Gap</b><p style="color:${gap<0?'#ad6d25':'#287954'}">${gap} percentage points</p></div></div><p>${E(p.description||'')}</p><div class="v5-actions">${button('แก้ไขข้อมูลโครงการ','projectTabV5="details";render()')}${button('ดูเอกสารล่าสุด ('+docs.filter(x=>x.latest).length+')','projectTabV5="files";render()','print-btn')}</div></div><div class="card"><h3>Workflow / Milestones</h3>${(p.tasks||[]).map(t=>`<div style="margin:13px 0"><div class="form-head"><span>${E(t.name)}</span><b>${t.progress}%</b></div><small>${E(t.start)} – ${E(t.end)}</small><div class="bar"><i style="width:${t.progress}%"></i></div></div>`).join('')}<div class="v5-actions">${button('จัดการ Gantt และกิจกรรม','projectTabV5="details";render()')}</div></div><div class="card"><h3>Project Files — Latest Revisions</h3>${docs.filter(x=>x.latest).slice(0,5).map(x=>`<div class="v5-file"><div><b>${E(x.name)}</b><br><small>${E(x.category)} · Rev ${E(x.rev)} · ${E(x.date)}</small></div>${button('ดาวน์โหลด',`downloadProjectFileV5('${E(x.id)}')`)}</div>`).join('')||'<p class="muted">ยังไม่มีไฟล์</p>'}</div>`}
let fileIndexV5=v4store('project_file_index',{});
function openFilesDBV5(){return new Promise((resolve,reject)=>{let r=indexedDB.open('CMANS_OFFLINE_FILES_V5',1);r.onupgradeneeded=()=>r.result.createObjectStore('files');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function saveBinaryV5(id,file){let db=await openFilesDBV5();return new Promise((res,rej)=>{let tx=db.transaction('files','readwrite');tx.objectStore('files').put(file,id);tx.oncomplete=()=>{db.close();res()};tx.onerror=()=>rej(tx.error)})}
async function readBinaryV5(id){let db=await openFilesDBV5();return new Promise((res,rej)=>{let tx=db.transaction('files','readonly');let q=tx.objectStore('files').get(id);q.onsuccess=()=>{db.close();res(q.result)};q.onerror=()=>rej(q.error)})}
function projectFilesPageV5(){let docs=fileIndexV5[selectedPID]||[];return `<div class="card"><h3>Project Document Register / ทะเบียนเอกสารโครงการ</h3>${projectSelectorV5()}<div class="v5-grid" style="margin-top:14px"><div class="v5-kpi"><small>เอกสารทั้งหมด</small><strong>${docs.length}</strong></div><div class="v5-kpi"><small>เอกสารล่าสุด</small><strong>${docs.filter(x=>x.latest).length}</strong></div><div class="v5-kpi"><small>Revisions เก่า</small><strong>${docs.filter(x=>!x.latest).length}</strong></div></div><div class="v5-note">ไฟล์ทดลองถูกเก็บใน IndexedDB ของเบราว์เซอร์เครื่องนี้เท่านั้น ยังไม่แชร์ให้ทีมงานเครื่องอื่นเห็นร่วมกัน</div><form id="fileFormV5" onsubmit="uploadProjectFileV5(event)"><div class="formgrid"><div><label>หมวดเอกสาร</label><select name="category">${optV4(['Drawings','Shop Drawing','As-built','3D Model','BOQ','Contract','RFA','Site Report','Meeting Minutes','Other'],'Drawings')}</select></div>${fV4('Document Code (ใช้รหัสเดิมเพื่ออัปเดต Revision)','code','DWG-001')}${fV4('Revision','rev','A')}${fV4('อัปโหลดโดย','author','CMANS Team')}<div class="full"><label>เลือกไฟล์ PDF / DWG / SKP / XLSX / JPG / อื่น ๆ</label><input name="file" type="file" required accept=".pdf,.dwg,.skp,.xlsx,.xls,.docx,.jpg,.jpeg,.png,.zip,.ifc,.rvt"></div></div><div class="v5-actions"><button type="submit" class="submit-btn">อัปโหลดไฟล์ Revision ใหม่</button></div></form></div><div class="card"><h3>Document Register / ดาวน์โหลดไฟล์</h3><div class="v5-file"><b>Document / Revision</b><b>Status</b><b>Action</b></div>${docs.map(d=>`<div class="v5-file"><div><b>${E(d.code)} · ${E(d.name)}</b><br><small>${E(d.category)} · Rev ${E(d.rev)} · ${E(d.author)} · ${E(d.date)} · ${(d.size/1024).toFixed(1)} KB</small></div><span class="pill ${d.latest?'good':''}">${d.latest?'LATEST':'SUPERSEDED'}</span>${button('ดาวน์โหลด',`downloadProjectFileV5('${E(d.id)}')`,'secondary')}</div>`).join('')||'<p class="muted">ยังไม่มีไฟล์ที่อัปโหลด</p>'}</div>`}
async function uploadProjectFileV5(ev){ev.preventDefault();let d=new FormData(document.getElementById('fileFormV5'));let f=d.get('file');if(!f||!f.size)return alert('กรุณาเลือกไฟล์');let code=String(d.get('code')||'').trim();if(!code)return alert('กรุณากรอกรหัสเอกสาร');let id='file-'+Date.now()+'-'+Math.floor(Math.random()*99999);try{await saveBinaryV5(id,f);let list=fileIndexV5[selectedPID]||[];list.forEach(x=>{if(x.code.toLowerCase()===code.toLowerCase())x.latest=false});list.unshift({id,code,name:f.name,category:d.get('category'),rev:d.get('rev'),author:d.get('author'),date:new Date().toLocaleString('th-TH'),size:f.size,latest:true});fileIndexV5[selectedPID]=list;v4save('project_file_index',fileIndexV5);logV4('อัปโหลดเอกสารโครงการ',code+' / '+f.name);render()}catch(e){alert('ไม่สามารถบันทึกไฟล์ในเบราว์เซอร์ได้: '+e.message)}}
async function downloadProjectFileV5(id){try{let f=await readBinaryV5(id);if(!f)return alert('ไฟล์นี้ไม่มีอยู่ในเบราว์เซอร์เครื่องนี้');let a=document.createElement('a');let url=URL.createObjectURL(f);a.href=url;a.download=f.name||'document';a.click();setTimeout(()=>URL.revokeObjectURL(url),1500)}catch(e){alert('ดาวน์โหลดไม่สำเร็จ: '+e.message)}}
function projectWorkspaceV5(){return projectButtonsV5()+(projectTabV5==='details'?projectDetail():projectTabV5==='files'?projectFilesPageV5():projectOverviewV5())}
/* BOQ selection: update only the selected row, preserving every unsaved input. */
chooseMaterialV4=function(i,code){syncBoqV4();let m=materialDB.find(x=>x.code===code);if(m){boqDB[i]={...boqDB[i],material:code,desc:m.name,unit:m.unit,materialPrice:Number(m.material),laborPrice:Number(m.labor)}}else boqDB[i].material='';let prefix=['bd','bu','bp','bl'];let b=boqDB[i];[b.desc,b.unit,b.materialPrice,b.laborPrice].forEach((v,j)=>{let el=document.getElementById(prefix[j]+i);if(el)el.value=v});updateBoqV4()};
/* Non-popup preview: keeps the form visible in a modal and prints from iframe. */
function showPrintPreviewV5(html,title){let old=document.getElementById('cmansPreview');if(old)old.remove();let shell=document.createElement('div');shell.id='cmansPreview';shell.innerHTML=`<div class="preview-shell"><div class="preview-bar"><strong>${E(title)}</strong><div class="v5-actions" style="margin:0"><button class="primary" type="button" id="v5PrintBtn">พิมพ์ / Save as PDF</button><button class="secondary" type="button" id="v5CloseBtn">ปิด</button></div></div><iframe title="ตัวอย่างเอกสาร" sandbox="allow-same-origin allow-modals"></iframe></div>`;document.body.append(shell);let frame=shell.querySelector('iframe');frame.srcdoc=html;shell.querySelector('#v5CloseBtn').onclick=()=>shell.remove();shell.querySelector('#v5PrintBtn').onclick=()=>{try{frame.contentWindow.focus();frame.contentWindow.print()}catch(e){alert('พิมพ์ไม่ได้: '+e.message)}};shell.addEventListener('click',e=>{if(e.target===shell)shell.remove()})}
const printCSSV5=`@page{size:A4;margin:15mm}*{box-sizing:border-box}body{font:12px Arial,'Noto Sans Thai',sans-serif;color:#1f2e45;background:white;margin:0}header{display:flex;align-items:center;justify-content:space-between;border-bottom:3px solid #20324d;padding-bottom:15px;margin-bottom:18px}header img{width:150px;max-height:55px;object-fit:contain}h1{font-size:19px;margin:0;color:#20324d}h2{font-size:13px;color:#20324d;background:#edf2f8;padding:9px;margin:18px 0 7px}p{line-height:1.7}table{width:100%;border-collapse:collapse;table-layout:fixed}th,td{border:1px solid #b7c3d1;padding:7px;text-align:left;vertical-align:top;overflow-wrap:anywhere}th{background:#f0f4f9}tr{break-inside:avoid}.sign{display:flex;gap:16px;margin-top:65px;page-break-inside:avoid}.sign div{flex:1;border-top:1px solid #75849a;text-align:center;padding-top:9px;line-height:2}.fine{color:#66778f;font-size:10px}.cover{min-height:680px;display:flex;flex-direction:column;justify-content:center;align-items:center;text-align:center}.page-break{page-break-before:always}`;
function printDocumentV5(type){const types={BOQ:'BILL OF QUANTITIES',QT:'QUOTATION / ใบเสนอราคา',LETTER:'OFFICIAL CORRESPONDENCE / หนังสือแจ้งผล',HANDOVER:'WORK HANDOVER / หนังสือส่งมอบงาน',CLAIM:'EXPENSE / TRAVEL CLAIM',BOOKLET:'PROJECT HANDOVER DOSSIER / รูปเล่มส่งมอบงาน'};let rows='',sections='',signs=['Prepared by','Reviewed by','Approved by'];let form=document.querySelector(type==='QT'?'#quote-form':type==='LETTER'?'#letter-form':type==='HANDOVER'?'#handover-form':type==='CLAIM'?'#claim-form':'#boq-form');let data=form?Object.fromEntries(new FormData(form).entries()):{};const info=(label,val)=>`<tr><th style="width:32%">${E(label)}</th><td>${E(val||'—')}</td></tr>`;
if(type==='BOQ'){syncBoqV4();rows=info('Project',projectName(boqProject))+info('Document date',dateNow());let sum=0;sections=`<h2>ITEMIZED BILL OF QUANTITIES</h2><table><thead><tr><th style="width:7%">No.</th><th>Description</th><th>Unit</th><th>Qty</th><th>Material / Unit</th><th>Labor / Unit</th><th>Amount (THB)</th></tr></thead><tbody>${boqDB.map((x,i)=>{let t=x.qty*(x.materialPrice+x.laborPrice);sum+=t;return `<tr><td>${i+1}</td><td>${E(x.desc)}</td><td>${E(x.unit)}</td><td>${x.qty}</td><td>${currency(x.materialPrice)}</td><td>${currency(x.laborPrice)}</td><td>${currency(t)}</td></tr>`}).join('')}<tr><th colspan="6">Subtotal</th><th>${currency(sum)}</th></tr><tr><td colspan="6">Overhead & Profit 10% (demo)</td><td>${currency(sum*.1)}</td></tr><tr><th colspan="6">Total before VAT</th><th>${currency(sum*1.1)}</th></tr></tbody></table>`}
if(type==='QT'){syncQuoteV4();let sum=quoteLines.reduce((s,x)=>s+x.qty*x.price,0);let discount=Number(data.discount||0),vat=Number(data.vat||7);rows=info('Quotation No.',data.ref)+info('Date',data.date)+info('Client',data.client)+info('Address',data.address)+info('Tax ID',data.tax)+info('Project',projectName(data.project))+info('Service Type',data.type)+info('Duration',data.duration)+info('Payment Terms',data.payment);sections=`<h2>SCOPE OF SERVICES & FEES</h2><table><tr><th>No.</th><th>Description</th><th>Qty</th><th>Unit</th><th>Unit Price</th><th>Amount</th></tr>${quoteLines.map((x,i)=>`<tr><td>${i+1}</td><td>${E(x.desc)}</td><td>${x.qty}</td><td>${E(x.unit)}</td><td>${currency(x.price)}</td><td>${currency(x.qty*x.price)}</td></tr>`).join('')}<tr><th colspan="5">Subtotal</th><th>${currency(sum)}</th></tr><tr><td colspan="5">Discount</td><td>${currency(discount)}</td></tr><tr><td colspan="5">VAT ${vat}%</td><td>${currency((sum-discount)*vat/100)}</td></tr><tr><th colspan="5">GRAND TOTAL</th><th>${currency((sum-discount)*(1+vat/100))}</th></tr></table><p class="fine">This quotation is subject to confirmation and acceptance by both parties.</p>`;signs=['Prepared / Authorized by CMANS','Accepted by Client']}
if(type==='LETTER'){rows=info('Letter No.',data.ref)+info('Date',data.date)+info('Project',projectName(data.project))+info('To / Attn.',data.attn||data.recipient||data.vendor)+info('Subject',data.subject);sections=`<h2>LETTER</h2><p>เรียน ${E(data.attn||data.recipient||data.vendor||'ผู้เกี่ยวข้อง')}</p><p style="white-space:pre-wrap;min-height:150px">${E(data.body||'')}</p><p>ขอแสดงความนับถือ</p>`;signs=['Authorized Signature / CMANS','Name / Position / Date']}
if(type==='HANDOVER'){syncHandoverV4();rows=info('Document No.',data.ref)+info('Date',data.date)+info('Project',projectName(data.project))+info('To / Recipient',data.recipient)+info('Milestone',data.milestone)+info('Sender',data.sender);sections=`<h2>LETTER OF HANDOVER</h2><p>บริษัทขอส่งมอบงานตามรายละเอียดโครงการและงวดงานที่ระบุไว้ พร้อมเอกสารประกอบดังต่อไปนี้</p><table><tr><th>No.</th><th>Deliverable</th><th>Qty</th><th>Unit</th><th>Remark</th></tr>${handoverRows.map((x,i)=>`<tr><td>${i+1}</td><td>${E(x.name)}</td><td>${x.qty}</td><td>${E(x.unit)}</td><td>${E(x.note)}</td></tr>`).join('')}</table><p><b>Outstanding / Remarks:</b> ${E(data.notes||'—')}</p>`;signs=['Submitted by CMANS','Received / Acknowledged by Client']}
if(type==='CLAIM'){rows=Object.entries(data).filter(([k])=>k!=='receipt').map(([k,v])=>info(k,v)).join('');sections=`<h2>CLAIM SUMMARY</h2><p>Claim type: ${E(claimMode)} · Amount: ${fmt(updateClaimV4())}</p>`}
if(type==='BOOKLET'){let p=projectDB.find(x=>x.id===selectedPID)||projectDB[0];rows=info('Project',p.name)+info('Project Code',p.id)+info('Client',p.client)+info('Scope',p.description)+info('Location',p.location)+info('Contract / Project Type',p.type)+info('Date',dateNow());let docs=(fileIndexV5[p.id]||[]).filter(x=>x.latest);sections=`<div class="page-break"></div><h2>TABLE OF CONTENTS / สารบัญ</h2><table>${['1. Executive Summary / สรุปโครงการ','2. Scope of Work / ขอบเขตงาน','3. Work Completion & Milestones / รายการงานที่แล้วเสร็จ','4. Approved / As-built Drawings / แบบส่งมอบ','5. Material & Equipment Register / รายการวัสดุอุปกรณ์','6. Testing & Commissioning / ผลทดสอบและตรวจรับ','7. Warranties, Manuals & Certificates / รับประกันและคู่มือ','8. Defect / Punch List / รายการคงค้าง','9. Document Register / ทะเบียนเอกสาร','10. Handover Certificate & Signatures / ใบรับมอบงาน'].map(x=>`<tr><td>${E(x)}</td></tr>`).join('')}</table><h2>PROJECT DOCUMENT REGISTER</h2><table><tr><th>Code</th><th>File</th><th>Rev</th><th>Category</th></tr>${docs.map(x=>`<tr><td>${E(x.code)}</td><td>${E(x.name)}</td><td>${E(x.rev)}</td><td>${E(x.category)}</td></tr>`).join('')||'<tr><td colspan="4">No files uploaded</td></tr>'}</table><p class="fine">รายการสารบัญเป็นโครงสร้างเสนอแนะ ยังต้องแนบไฟล์จริงและตรวจความครบถ้วนก่อนออกเล่มส่งมอบ</p>`;signs=['Prepared by CMANS','Reviewed by','Received by Client']}
let html=`<!doctype html><html lang="th"><head><meta charset="utf-8"><title>CMANS ${type}</title><style>${printCSSV5}</style></head><body><header><img alt="CMANS" src="${logoV5}"><div style="text-align:right"><h1>${types[type]}</h1><small>CMANS · ${dateNow()}</small></div></header><h2>DOCUMENT DETAILS</h2><table>${rows}</table>${sections}<div class="sign">${signs.map(s=>`<div>...........................................<br>${E(s)}<br>Name / Date: ........................</div>`).join('')}</div><p class="fine">CMANS Office Hub · Prototype document · Please verify before official issue</p></body></html>`;showPrintPreviewV5(html,types[type])}
printGenericV4=printDocumentV5;
/* BOQ print must not depend on hidden popup or querySelector('.card'). */
function printBoqV5(){printDocumentV5('BOQ')}
function dailyWorkV5(){let total=dailyLinesV5.reduce((s,x,i)=>s+Number(document.getElementById('wh'+i)?.value??x.hours),0);let byProject={};dailyLogsV5.forEach(l=>l.items.forEach(i=>{byProject[i.project]=(byProject[i.project]||0)+Number(i.hours)}));return `<div class="card"><h3>Daily Work Log / บันทึกงานพนักงาน</h3><p class="muted">Architect · Engineer · Graphic Designer · Project Coordinator</p><form id="workFormV5" onsubmit="saveDailyWorkV5(event)"><div class="formgrid">${fV4('วันที่','date',dateNow(),'date')}${fV4('ชื่อพนักงาน','employee','')}<div><label>ตำแหน่ง</label><select name="position">${optV4(['Architect','Engineer','Graphic Designer','Project Coordinator','Other'],'Architect')}</select></div>${fV4('หัวหน้าทีม / ผู้ตรวจ','supervisor','')}</div><h3 class="section-title">รายการงานในวันนี้</h3>${dailyLinesV5.map((l,i)=>`<div class="entry"><div class="form-head"><b>งานที่ ${i+1}</b>${button('ลบ',`removeDailyLineV5(${i})`,'danger-outline')}</div><div class="formgrid"><div><label>โครงการ</label><select id="wp${i}">${projectDB.map(p=>`<option value="${E(p.id)}" ${p.id===l.project?'selected':''}>${E(p.name)}</option>`).join('')}</select></div>${fV4('งานที่ได้รับมอบหมาย','wt'+i,l.task)}<div><label>ประเภทงาน</label><select id="wc${i}">${optV4(['CAD','3D Modeling','Rendering','Site Inspection','Meeting','Coordination','Graphic Design','BOQ','Documentation','Other'],l.category)}</select></div>${fV4('ชั่วโมงที่ใช้','wh'+i,l.hours,'number','min="0" max="24" step="0.25"')}${fV4('ความคืบหน้า (%)','wpr'+i,l.progress,'number','min="0" max="100"')}<div class="full"><label>รายละเอียดงานที่ทำ</label><textarea id="wd${i}">${E(l.description)}</textarea></div><div class="full"><label>ปัญหา / ต้องการความช่วยเหลือ</label><textarea id="wi${i}">${E(l.issues)}</textarea></div><div class="full"><label>แผนงานวันถัดไป</label><textarea id="wn${i}">${E(l.next)}</textarea></div>${fV4('Google Drive / ผลงาน (URL)','wl'+i,l.link||'')}<div><label>แนบไฟล์ผลงาน (Demo)</label><input type="file" id="wf${i}" multiple></div></div></div>`).join('')}<div class="v5-actions">${button('+ เพิ่มงาน','addDailyLineV5()')}<button class="submit-btn" type="submit">บันทึก Daily Work Log</button></div></form><p class="v5-note">Prototype เก็บข้อมูลรายการและลิงก์ไว้ในเบราว์เซอร์ ไฟล์แนบในฟอร์มนี้ยังไม่อัปโหลดขึ้นระบบกลาง</p></div><div class="card"><h3>Workload & Project Hours</h3><div class="v5-grid">${Object.entries(byProject).map(([id,h])=>`<div class="v5-kpi"><small>${E(projectName(id))}</small><strong>${h.toFixed(1)} ชม.</strong></div>`).join('')||'<p class="muted">บันทึกงานเพื่อดูสรุปชั่วโมงตามโครงการ</p>'}</div><h3 class="section-title">รายการบันทึกล่าสุด</h3><div class="scroll"><table><tr><th>วันที่</th><th>พนักงาน</th><th>ตำแหน่ง</th><th>จำนวนงาน</th><th>ชั่วโมง</th></tr>${dailyLogsV5.map(l=>`<tr><td>${E(l.date)}</td><td>${E(l.employee)}</td><td>${E(l.position)}</td><td>${l.items.length}</td><td>${l.items.reduce((s,x)=>s+Number(x.hours),0)}</td></tr>`).join('')}</table></div></div>`}
function syncDailyV5(){dailyLinesV5=dailyLinesV5.map((l,i)=>({project:get('wp'+i)||l.project,task:get('wt'+i),category:get('wc'+i),hours:Number(get('wh'+i)),progress:Number(get('wpr'+i)),description:get('wd'+i),issues:get('wi'+i),next:get('wn'+i),link:get('wl'+i)}))}
function addDailyLineV5(){syncDailyV5();dailyLinesV5.push({project:projectDB[0]?.id||'',task:'',category:'CAD',description:'',hours:1,progress:0,issues:'',next:'',link:''});render()}
function removeDailyLineV5(i){syncDailyV5();if(dailyLinesV5.length>1)dailyLinesV5.splice(i,1);render()}
function saveDailyWorkV5(ev){ev.preventDefault();syncDailyV5();let d=formDataV4('workFormV5');if(!d.employee.trim())return alert('กรุณากรอกชื่อพนักงาน');let total=dailyLinesV5.reduce((s,x)=>s+x.hours,0);if(total>24)return alert('ชั่วโมงรวมต่อวันต้องไม่เกิน 24 ชั่วโมง');dailyLogsV5.unshift({...d,items:structuredClone(dailyLinesV5),ref:'WORK-'+Date.now()});persistV4('dailywork',dailyLogsV5,'บันทึก Daily Work Log',d.employee)}
function handoverWorkspaceV5(){return `<div class="project-tabs"><button class="${handoverModeV5==='letter'?'primary':'secondary'}" onclick="handoverModeV5='letter';render()">1. หนังสือส่งมอบงาน / เซ็นรับ</button><button class="${handoverModeV5==='booklet'?'primary':'secondary'}" onclick="handoverModeV5='booklet';render()">2. รูปเล่มส่งมอบงาน</button></div>${handoverModeV5==='letter'?handoverPage():handoverBookletV5()}`}
function handoverBookletV5(){let p=projectDB.find(x=>x.id===selectedPID)||projectDB[0];let docs=(fileIndexV5[p.id]||[]).filter(x=>x.latest);return `<div class="card"><h3>Project Handover Booklet / รูปเล่มส่งมอบงาน</h3><p class="muted">จัดรูปเล่มเอกสารส่งมอบโครงการ โดยอ้างอิงข้อมูลโครงการและทะเบียนเอกสารล่าสุด</p>${projectSelectorV5()}<div class="v5-grid" style="margin-top:15px"><div class="v5-kpi"><small>โครงการ</small><strong style="font-size:17px">${E(p.name)}</strong></div><div class="v5-kpi"><small>ไฟล์ล่าสุดในทะเบียน</small><strong>${docs.length}</strong></div></div><h3 class="section-title">สารบัญแนะนำ</h3><div class="scroll"><table><tr><th>หมวด</th><th>รายละเอียด</th></tr>${[['01','Cover, Document Control & Revision'],['02','Executive Summary / ข้อมูลโครงการ'],['03','Scope of Work & Contract Reference'],['04','Completion Report / สรุปงานที่ดำเนินการ'],['05','Approved / As-built Drawings (PDF / DWG)'],['06','Material & Equipment Register'],['07','Testing & Commissioning / Inspection'],['08','Warranty, Certificates & O&M Manuals'],['09','Defect / Punch List & Outstanding Work'],['10','Document Register / รายการเอกสารแนบ'],['11','Handover Certificate / ใบรับมอบงานและลายเซ็น']].map(x=>`<tr><td>${x[0]}</td><td>${x[1]}</td></tr>`).join('')}</table></div><h3 class="section-title">รายการเอกสารที่จะอ้างอิง</h3>${docs.map(x=>`<div class="v5-file"><div>${E(x.code)} — ${E(x.name)} <span class="tag">Rev ${E(x.rev)}</span></div>${button('ดาวน์โหลด',`downloadProjectFileV5('${E(x.id)}')`)}</div>`).join('')||'<p class="muted">ยังไม่มีเอกสารโครงการ กรุณาอัปโหลดในเมนู Project Files</p>'}<div class="v5-actions">${button('ดูตัวอย่างหน้าปก / สารบัญ / ใบลงนาม','printDocumentV5("BOOKLET")','print-btn')}${button('ไปหน้าเอกสารโครงการ','projectTabV5="files";setPage("projects")')}</div><p class="v5-note">ตัวอย่างพิมพ์เฉพาะหน้าปก สารบัญ และทะเบียนเอกสาร ยังไม่รวมไฟล์ PDF / DWG / SKP จริงเป็นรูปเล่มเดียว</p></div>`}
/* Letter recipient should be freely typed, not limited to Vendor master. */
const previousLettersV5=lettersPage;
lettersPage=function(){let h=previousLettersV5();h=h.replace(/<div><label>ผู้รับ \(Vendor\)<\/label><select name="vendor">[\s\S]*?<\/select><\/div>/,fV4('ผู้รับ / บริษัท / หน่วยงาน (พิมพ์เองได้)','recipient',''));return h};
/* Quote and letter print buttons are replaced with modal previews, not popups. */
const originalQuoteV5=quotePage;
quotePage=function(){let h=originalQuoteV5();return h.replace('printGenericV4("QT")','printDocumentV5("QT")')};
const originalHandoverV5=handoverPage;
handoverPage=function(){let h=originalHandoverV5();return h.replace('printGenericV4("HANDOVER")','printDocumentV5("HANDOVER")')};
const originalBoqV5=boqEstimate;
boqEstimate=function(){let h=originalBoqV5();return h.replace('printGenericV4("BOQ")','printBoqV5()')};
/* Vendor columns: colored vertical bands from header through all table rows. */
applyCompareColorsV4=function(){let table=document.querySelector('.comparison');if(!table)return;let colors=['#4169A4','#287954','#AD7734','#865EA5','#B45353','#397C8E','#6A6F43','#9B6487'];let legend=document.createElement('div');legend.className='v5-compare-legend';vendorsV2.forEach((v,j)=>{let s=document.createElement('span');s.style.background=colors[j%colors.length];s.textContent=v.name;legend.append(s)});table.parentElement.before(legend);for(let j=0;j<vendorsV2.length;j++){let color=colors[j%colors.length];table.querySelectorAll('tr').forEach(tr=>{let cell=tr.children[4+j];if(!cell)return;cell.style.backgroundColor=color+'20';cell.style.borderLeft='4px solid '+color;cell.style.borderRight='2px solid '+color+'77';if(cell.tagName==='TH'){cell.style.backgroundColor=color;cell.style.color='white';cell.querySelectorAll('small').forEach(s=>s.style.color='white')}})}};
/* Grouped sidebar and project subpages. */
for(let [g,items] of groupsV4){if(g==='OVERVIEW'){items.splice(1,1,['projects','▣','โครงการ / Project Workspace'])}if(g==='OPERATIONS & FINANCE'){items.splice(1,0,['dailywork','▤','Daily Work Log'])}}
if(!nav.some(x=>x[0]==='dailywork'))nav.push(['dailywork','▤','Daily Work Log']);
const oldRenderV5=render;
render=function(){oldRenderV5();let overrides={projects:projectWorkspaceV5,dailywork:dailyWorkV5,handover:handoverWorkspaceV5,boq:boqEstimate,quotation:quotePage,letters:lettersPage};if(overrides[active])document.getElementById('content').innerHTML=overrides[active]();document.getElementById('heading').textContent=nav.find(x=>x[0]===active)?.[2]||'CMANS Office Hub'};
